const p = $json.body || $json;
const event = p.event || p;
const msg = event.payload || event.message || event;
const phone = String(msg.from || msg.chatId || p.from || '').replace(/@c\.us$/,'');
const text = String(msg.body || msg.text || p.body || p.text || '').trim();
return [{json:{phone,text,customer_name:msg.pushName || p.pushName || '',raw:p}}];

const input = $('Normalizar mensagem').item.json;
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const key = input.phone;
const s = store.sessions[key] || {step:'menu', items:[], mode:'', name:'', address:'', payment:''};
const text = input.text.toLowerCase().trim();
const menu = 'Olá! Sou o atendimento do Zelda PDV. Escolha uma opção: 1 Fazer pedido, 2 Consultar pedido, 3 Ver cardápio, 4 Registrar elogio ou reclamação, 5 Falar com atendente humano.';
let out={...input,action:'reply',reply:menu};
if (!text) return [{json:out}];
if (s.step === 'human') { out.action='human'; out.reply='Seu atendimento está com a equipe humana. Aguarde uma mensagem.'; return [{json:out}]; }
if (['menu','inicio','início'].includes(s.step)) {
  if (/^(1|pedido|fazer pedido)/.test(text)) {s.step='mode';out.reply='Seu pedido será para entrega ou retirada no local? Responda entrega ou retirada.';}
  else if (/^(2|status|consultar)/.test(text)) {s.step='status';out.reply='Informe o número do pedido, por exemplo 123.';}
  else if (/^(3|cardapio|cardápio|menu)/.test(text)) {out.reply='Ainda não temos cardápio digital disponível. Em breve teremos. Obrigado e até logo!';s.step='menu';}
  else if (/^(4|elogio|reclama|feedback)/.test(text)) {s.step='feedback';out.reply='Envie seu elogio ou reclamação em uma única mensagem.';}
  else if (/^(5|humano|atendente)/.test(text)) {s.step='human';out.action='human';out.reply='Vou transferir você para um atendente humano. Informe brevemente o assunto.';}
  else out.reply=menu;
} else if (s.step==='mode') {
  if (/entrega|delivery/.test(text)) {s.mode='delivery';s.step='name';out.reply='Informe seu nome completo.';}
  else if (/retirada|retirar|local|pickup/.test(text)) {s.mode='takeout';s.step='name';out.reply='Informe seu nome completo.';}
  else out.reply='Responda apenas entrega ou retirada.';
} else if (s.step==='name') {s.name=input.text;s.step=s.mode==='delivery'?'address':'payment';out.reply=s.mode==='delivery'?'Informe o endereço completo para entrega.':'Qual será a forma de pagamento: dinheiro, cartão ou pix?';}
else if (s.step==='address') {s.address=input.text;s.step='payment';out.reply='Qual será a forma de pagamento: dinheiro, cartão ou pix?';}
else if (s.step==='payment') { if (!/dinheiro|cart[aã]o|pix/.test(text)) out.reply='Escolha dinheiro, cartão ou pix.'; else {s.payment=/pix/.test(text)?'pix':/cart/.test(text)?'cartao':'dinheiro';s.step='items';out.reply='Informe os produtos e quantidades. Exemplo: 1 Zelda Burger e 2 Refrigerante Lata.';} }
else if (s.step==='items') {
  const catalog=[{id:1001,title:'Zelda Burger',price:28.9},{id:1002,title:'X-Bacon Zelda',price:34.9},{id:1003,title:'Refrigerante Lata',price:6.5}];
  const items=[]; for (const p of catalog) { const m=text.match(new RegExp('(\d+)\s*(?:x\s*)?'+p.title.toLowerCase().replace(' ','\\s+'),'i')); if(m) items.push({...p,quantity:Math.min(Number(m[1]),20)}); else if(text.includes(p.title.toLowerCase())) items.push({...p,quantity:1}); }
  if (!items.length) out.reply='Não identifiquei os produtos. Use os nomes do cardápio, por exemplo: 1 Zelda Burger e 1 Refrigerante Lata.'; else {out.action='create_order';out.items=items;s.items=items;s.customer_name=s.name;s.address=s.address;s.mode=s.mode;s.payment=s.payment;out.mode=s.mode;out.name=s.name;out.address=s.address;out.payment=s.payment;store.sessions[key]= {step:'menu'};out.reply='';}
} else if (s.step==='status') {const id=Number(text.replace(/\D/g,'')); if(!id) out.reply='Informe apenas o número do pedido.'; else {out.action='status';out.order_id=id;s.step='menu';}}
else if (s.step==='feedback') {out.action='feedback';out.feedback_type=/reclama|problema|ruim/.test(text)?'reclamacao':'elogio';out.feedback_message=input.text;s.step='menu';}
store.sessions[key]=s;
return [{json:out}];
